module corpus.algorithms.bubblesort;

><salivo.std.core::{outln};
><salivo.std.collections::{Vec, vecNew, push, set, get, veclen};

pub func bubbleSort(list: Vec<int>) {
    let n = veclen<int>(list);
    for (let mut i = 0; i < n; i = i + 1) {
        let limit = n - i - 1;
        for (let mut j = 0; j < limit; j = j + 1) {
            let next_idx = j + 1;
            let a = get<int>(list, j);
            let b = get<int>(list, next_idx);
            if (a > b) {
                // Swap in-place
                set<int>(list, j, b);
                set<int>(list, next_idx, a);
            }
        }
    }
}

pub func main() -> int {
    let mut arr = vecNew<int>();
    arr = push<int>(arr, 64);
    arr = push<int>(arr, 25);
    arr = push<int>(arr, 12);
    arr = push<int>(arr, 22);
    arr = push<int>(arr, 11);

    bubbleSort(arr);

    let count = veclen<int>(arr);
    for (let mut k = 0; k < count; k = k + 1) {
        let val = get<int>(arr, k);
        outln($"Sorted element {k:str}: {val:str}");
    }

    return 0;
}

module corpus.algorithms.binarysearch;

><salivo.std.core::{outln, Option, some, none};
><salivo.std.collections::{Vec, vecNew, push, get, veclen};

pub func binarySearch(sorted_list: Vec<int>, target: int) -> Option<int> {
    let mut low: int = 0;
    let mut high: int = veclen<int>(sorted_list) - 1;

    while (low <= high) {
        let mid: int = (low + high) / 2;
        let mid_val: int = get<int>(sorted_list, mid);

        if (mid_val == target) {
            return some(mid);
        } else if (mid_val < target) {
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return none();
}

pub func main() -> int {
    let mut numbers = vecNew<int>();
    numbers = push<int>(numbers, 10);
    numbers = push<int>(numbers, 20);
    numbers = push<int>(numbers, 30);
    numbers = push<int>(numbers, 40);
    numbers = push<int>(numbers, 50);

    let found = binarySearch(numbers, 30);
    let missing = binarySearch(numbers, 99);

    outln("Binary search completed successfully.");
    return 0;
}

