pub func fibIterative(n: int) -> int {
    if (n <= 0) {
        return 0;
    }
    if (n == 1) {
        return 1;
    }

    let mut a: int = 0;
    let mut b: int = 1;

    for (let mut i = 2; i <= n; i = i + 1) {
        let next_val = a + b;
        a = b;
        b = next_val;
    }
    return b;
}

pub func factorial(n: int) -> int {
    if (n <= 1) {
        return 1;
    }
    return n * factorial(n - 1);
}

pub func main() -> int {
    let fib_7 = fibIterative(7);
    let fact_5 = factorial(5);

    outln($"Fibonacci(7): {fib_7:str}");
    outln($"Factorial(5): {fact_5:str}");

    return 0;
}

module corpus.algorithms.gcd;

><salivo.std.core::{outln};

pub func gcd(a: int, b: int) -> int {
    let mut x: int = a;
    let mut y: int = b;

    while (y != 0) {
        let remainder = x % y;
        x = y;
        y = remainder;
    }
    return x;
}

pub func lcm(a: int, b: int) -> int {
    if (a == 0 || b == 0) {
        return 0;
    }
    let common_divisor = gcd(a, b);
    return (a * b) / common_divisor;
}

pub func main() -> int {
    let g = gcd(48, 18);
    let l = lcm(12, 15);

    outln($"GCD(48, 18) = {g:str}");
    outln($"LCM(12, 15) = {l:str}");

    return 0;
}

